import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "npm:@supabase/supabase-js@2";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SERVICE_ROLE = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY")!;
const OPENAI_BASE_URL = "https://api.openai.com/v1";

const supabase = createClient(SUPABASE_URL, SERVICE_ROLE, { auth: { persistSession: false } });

interface Recall {
  id: string;
  text: string | null;
  latitude: number | null;
  longitude: number | null;
  location: string | null;
  created_at: string;
  updated_at: string;
  user_id: string;
}

interface SearchRequest {
  query: string;
  limit?: number;
}

interface ScoredRecall extends Recall {
  relevance_score: number;
  relevance_reason: string;
}

Deno.serve(async (req) => {
  try {
    if (req.method !== "POST") {
      return new Response("Method Not Allowed", { status: 405 });
    }

    // Auth
    const auth = req.headers.get("Authorization") || "";
    const { data: user } = await supabase.auth.getUser(auth.replace("Bearer ", ""));
    if (!user?.user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), { status: 401 });
    }

    const body = (await req.json()) as SearchRequest;
    const query = (body.query ?? "").trim();
    const limit = body.limit ?? 10;

    if (query.length < 2) {
      return new Response(
        JSON.stringify({ error: "Query must be at least 2 characters." }),
        { status: 400 }
      );
    }

    console.log("Searching recalls for user:", user.user.id, "query:", query);

    // Fetch all recalls for the user
    const { data: recalls, error: recallsError } = await supabase
      .from("recalls")
      .select("*")
      .eq("user_id", user.user.id)
      .order("created_at", { ascending: false });

    if (recallsError) {
      console.error("Error fetching recalls:", recallsError);
      return new Response(
        JSON.stringify({ error: "Failed to fetch recalls", detail: recallsError.message }),
        { status: 500 }
      );
    }

    if (!recalls || recalls.length === 0) {
      return new Response(
        JSON.stringify({ results: [], total: 0 }),
        { status: 200, headers: { "Content-Type": "application/json" } }
      );
    }

    console.log("Found", recalls.length, "recalls to analyze");

    // Use OpenAI to analyze and score recalls
    const systemPrompt = `You are an expert at analyzing and matching text data using Named Entity Recognition (NER) and semantic understanding.

Your task is to:
1. Extract named entities (people, places, organizations, dates, products, etc.) from both the search query and each recall
2. Analyze the semantic meaning and context of the search query
3. Compare the search query against each recall's text, location, latitude, and longitude
4. Score each recall based on relevance (0-100)
5. Provide a brief reason for the score

Consider:
- Exact matches should score highest
- Semantic similarity and related concepts
- Location proximity if coordinates are mentioned
- Entity matches (e.g., same person, place, or product)
- Contextual relevance

Return a JSON array of scored recalls, sorted by relevance_score (highest first), limited to top ${limit} results.`;

    const recallsData = recalls.map((r: Recall) => ({
      id: r.id,
      text: r.text || "",
      location: r.location || "",
      latitude: r.latitude,
      longitude: r.longitude,
    }));

    const userPrompt = `Search Query: "${query}"

Recalls to analyze:
${JSON.stringify(recallsData, null, 2)}

Analyze these recalls and return a JSON array with this exact structure:
[
  {
    "id": "recall-id",
    "relevance_score": 95,
    "relevance_reason": "Brief explanation of why this recall matches"
  }
]

Only include recalls with relevance_score > 0. Sort by relevance_score descending. Limit to top ${limit} results.`;

    console.log("Calling OpenAI for NER analysis...");

    const chatRes = await fetch(`${OPENAI_BASE_URL}/chat/completions`, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${OPENAI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userPrompt },
        ],
        temperature: 0.3,
        response_format: { type: "json_object" },
      }),
    });

    if (!chatRes.ok) {
      const errorText = await chatRes.text();
      console.error("OpenAI API error:", errorText);
      return new Response(
        JSON.stringify({ error: "OpenAI API error", detail: errorText }),
        { status: 502 }
      );
    }

    const chatJson: any = await chatRes.json();
    const responseText = chatJson?.choices?.[0]?.message?.content ?? "";

    if (!responseText) {
      console.error("Empty response from OpenAI");
      return new Response(
        JSON.stringify({ error: "Empty response from OpenAI" }),
        { status: 502 }
      );
    }

    console.log("OpenAI response:", responseText);

    let scoredRecallIds: Array<{ id: string; relevance_score: number; relevance_reason: string }>;
    try {
      const parsed = JSON.parse(responseText);
      // Handle both array and object with results array
      scoredRecallIds = Array.isArray(parsed) ? parsed : (parsed.results || []);
    } catch (e) {
      console.error("Failed to parse OpenAI response:", e);
      return new Response(
        JSON.stringify({ error: "Failed to parse AI response", detail: String(e) }),
        { status: 500 }
      );
    }

    // Merge scores with full recall data
    const scoredRecalls: ScoredRecall[] = scoredRecallIds
      .map((scored) => {
        const recall = recalls.find((r: Recall) => r.id === scored.id);
        if (!recall) return null;
        return {
          ...recall,
          relevance_score: scored.relevance_score,
          relevance_reason: scored.relevance_reason,
        };
      })
      .filter((r): r is ScoredRecall => r !== null)
      .sort((a, b) => b.relevance_score - a.relevance_score)
      .slice(0, limit);

    console.log("Returning", scoredRecalls.length, "scored recalls");

    return new Response(
      JSON.stringify({
        results: scoredRecalls,
        total: scoredRecalls.length,
        query,
      }),
      {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }
    );
  } catch (e) {
    console.error("Unhandled error:", e);
    return new Response(
      JSON.stringify({ error: "Unhandled error", detail: String(e) }),
      { status: 500 }
    );
  }
});

